const form=document.getElementById("creditForm"),result=document.getElementById("result");form&&form.addEventListener("submit",p=>{p.preventDefault();const s=parseFloat(document.getElementById("sum").value)||0,o=parseFloat(document.getElementById("rate").value)||0,a=parseInt(document.getElementById("term").value,10)||0,v=document.getElementById("type").value;if(s<=0||o<0||a<=0){result.innerHTML='<p style="margin:0;color:#c0392b">Введите сумму, ставку и срок больше нуля.</p>';return}const i=o/100/12;if(v==="annuity"){const n=i===0?s/a:s*i/(1-Math.pow(1+i,-a)),t=n*a,e=t-s;result.innerHTML=`
        <div class="result-list">
          <div class="item"><span>Сумма кредита</span><span class="val">${fmt(s)} ₽</span></div>
          <div class="item"><span>Ежемесячный платёж</span><span class="val">${fmt(n)} ₽</span></div>
          <div class="item"><span>Всего выплат</span><span class="val">${fmt(t)} ₽</span></div>
          <div class="item total"><span>Переплата (${fmt(e/s*100)}%)</span><span class="val">${fmt(e)} ₽</span></div>
        </div>
        <p class="hint" style="margin-top:14px">Тип платежа: аннуитетный.</p>
      `}else{const n=s/a;let t=0,e=0,m=0;for(let l=1;l<=a;l++){const d=(s-n*(l-1))*i,c=n+d;t+=c,l===1&&(e=c),l===a&&(m=c)}const r=t-s;result.innerHTML=`
        <div class="result-list">
          <div class="item"><span>Сумма кредита</span><span class="val">${fmt(s)} ₽</span></div>
          <div class="item"><span>Первый платёж</span><span class="val">${fmt(e)} ₽</span></div>
          <div class="item"><span>Последний платёж</span><span class="val">${fmt(m)} ₽</span></div>
          <div class="item"><span>Всего выплат</span><span class="val">${fmt(t)} ₽</span></div>
          <div class="item total"><span>Переплата (${fmt(r/s*100)}%)</span><span class="val">${fmt(r)} ₽</span></div>
        </div>
        <p class="hint" style="margin-top:14px">Тип платежа: дифференцированный.</p>
      `}});function fmt(p){return new Intl.NumberFormat("ru-RU",{maximumFractionDigits:2}).format(p)}
